[CmdletBinding(SupportsShouldProcess)]
param([Parameter(Mandatory)][ValidateNotNullOrEmpty()][string]$OutputDirectory,[ValidateSet('amd64','x86')][string]$Architecture='amd64',[ValidateRange(0,255)][int]$UsbDiskNumber=-1,[switch]$Force)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
function Find-AdkTool([string]$Name){$roots=@(${env:ProgramFiles(x86)},${env:ProgramFiles})|Where-Object{$_};foreach($root in $roots){$candidate=Join-Path $root "Windows Kits\10\Assessment and Deployment Kit\Deployment Tools\$Name";if(Test-Path $candidate){return $candidate}};throw "Could not find $Name. Install the Windows ADK Deployment Tools first."}
function Find-HtaPackage([string]$Arch){$roots=@(${env:ProgramFiles(x86)},${env:ProgramFiles})|Where-Object{$_};foreach($root in $roots){$candidate=Join-Path $root "Windows Kits\10\Assessment and Deployment Kit\Windows Preinstallation Environment\$Arch\WinPE_OCs\WinPE-HTA-Package.cab";if(Test-Path $candidate){return $candidate}};throw 'WinPE-HTA-Package.cab was not found. Install the Windows PE add-on for the ADK.'}
function Assert-Administrator{$i=[Security.Principal.WindowsIdentity]::GetCurrent();$p=[Security.Principal.WindowsPrincipal]::new($i);if(-not$p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Run this script from an elevated PowerShell window.'}}
Assert-Administrator;$copype=Find-AdkTool 'copype.cmd';$make=Find-AdkTool 'MakeWinPEMedia.cmd';$dism=(Get-Command dism.exe).Source;$source=Join-Path $OutputDirectory 'source';$mount=Join-Path $OutputDirectory 'mount';$media=Join-Path $OutputDirectory 'media';if(Test-Path $OutputDirectory){if(-not$Force){throw "Output directory already exists. Remove it or use -Force: $OutputDirectory"};Remove-Item $OutputDirectory -Recurse -Force};New-Item $OutputDirectory,$mount,$media -ItemType Directory -Force|Out-Null;&$copype $Architecture $source;if($LASTEXITCODE-ne 0){throw "copype failed with exit code $LASTEXITCODE"};$boot=Join-Path $source 'media\sources\boot.wim';&$dism /Mount-Image /ImageFile:$boot /Index:1 /MountDir:$mount;if($LASTEXITCODE-ne 0){throw 'Unable to mount boot.wim.'};try{$hta=Find-HtaPackage $Architecture;&$dism /Image:$mount /Add-Package /PackagePath:$hta;if($LASTEXITCODE-ne 0){throw 'Unable to add WinPE HTA package.'};$files='Start-Windows4Installer.ps1','Get-HardwareInventory.ps1','DeploymentEngine.ps1','HuskagentInstaller.hta','HuskagentDeployment.hta','Windows4Installer.cmd';foreach($file in $files){Copy-Item (Join-Path $PSScriptRoot $file) $mount -Force};$startup=Join-Path $mount 'Windows\System32\Startnet.cmd';Add-Content $startup "`r`n wpeinit`r`n powershell.exe -ExecutionPolicy Bypass -File X:\Start-Windows4Installer.ps1`r`n"}finally{&$dism /Unmount-Image /MountDir:$mount /Commit;if($LASTEXITCODE-ne 0){throw 'Unable to commit boot.wim changes.'}};if($UsbDiskNumber-ge 0){$disk=Get-Disk -Number $UsbDiskNumber;if($disk.BusType-ne 'USB' -and -not$Force){throw "Disk $UsbDiskNumber is $($disk.BusType), not USB. Use -Force only after verifying the disk."};if(-not$PSCmdlet.ShouldProcess("Disk $UsbDiskNumber ($($disk.FriendlyName))",'Erase and create WinPE USB media')){return};&$make /UFD $source ("\\.\PhysicalDrive$UsbDiskNumber")}else{&$make /ISO $source (Join-Path $media "HuskagentWindows4-Phase3-$Architecture.iso")};if($LASTEXITCODE-ne 0){throw "MakeWinPEMedia failed with exit code $LASTEXITCODE"};Write-Host "Phase 3 WinPE media created under $OutputDirectory" -ForegroundColor Green
